function validate([colors, k]) {
  if (colors.length < 3 || colors.length > 100000) return 'colors needs 3 to 100,000 tiles.';
  if (colors.some(c => c !== 0 && c !== 1)) return 'Each colour is 0 (red) or 1 (blue).';
  if (k < 3 || k > colors.length) return 'k is between 3 and colors.length.';
  return null;
}

