function numberOfAlternatingGroups(colors, k) {
  const n = colors.length;
  const same = (i) => colors[i % n] === colors[(i + 1) % n];
  let clashes = 0;

  for (let i = 0; i < k - 1; i++) {
    if (same(i)) {
      clashes++;
    }
  }
  let groups = clashes === 0 ? 1 : 0;

  for (let start = 1; start < n; start++) {
    if (same(start - 1)) {
      clashes--;
    }
    if (same(start + k - 2)) {
      clashes++;
    }
    if (clashes === 0) {
      groups++;
    }
  }
  return groups;
}

