function numberOfAlternatingGroups(colors, k) {
  const n = colors.length;
  let count = 0;
  for (let start = 0; start < n; start++) {
    const group = [];
    for (let step = 0; step < k; step++) group.push(colors[(start + step) % n]);
    if (group.every((color, j) => j === 0 || color !== group[j - 1])) count++;
