function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(3, 12);
  // Start from a perfectly alternating circle and recolour a few tiles, so long alternating runs exist.
  const first = int(0, 1);
  const colors = Array.from({ length: n }, (_, i) => (first + i) % 2);
  const flips = rand() < 0.2 ? 0 : int(1, size === 'large' ? 8 : 3);
  for (let f = 0; f < flips; f++) {
    const i = int(0, n - 1);
    colors[i] = 1 - colors[i];
  }
  if (rand() < 0.15) for (let i = 0; i < n; i++) colors[i] = int(0, 1);
  const k = rand() < 0.2 ? n : int(3, size === 'large' ? 300 : n);
  return [colors, k];
}
